using System;
using System.Collections.Generic;
using System.IO;
using TMPro;
using UnityEngine;
using UnityEngine.TextCore.LowLevel;

namespace BluePrinceArabic
{
    // Arabic TMP font assets, one per visual style, registered as the first fallback of every game font asset
    // so Arabic glyphs follow the look of the Latin font that the object uses (handwriting, typewriter, serif, display...).
    public static class ArabicFont
    {
        // style -> TTF in <plugin>/fonts (generated by tools/make_pf_font.py so the presentation forms exist)
        static readonly string[][] Files =
        {
            new[] { "serif", "Amiri-Regular.ttf" },
            new[] { "sans", "IBMPlexSansArabic-Medium.ttf" },
            new[] { "display", "Lalezar-Regular-PF.ttf" },
            new[] { "hand", "Mirza-Bold-PF.ttf" },
            new[] { "script", "Katibeh-Regular-PF.ttf" },
            new[] { "quirky", "Rakkas-Regular-PF.ttf" },
            new[] { "sansbold", "IBMPlexSansArabic-Bold.ttf" },
            new[] { "serifbold", "Amiri-Bold.ttf" },
            new[] { "serifitalic", "Amiri-Italic.ttf" },
        };

        static readonly Dictionary<string, TMP_FontAsset> styles = new Dictionary<string, TMP_FontAsset>();
        static readonly Dictionary<int, TMP_FontAsset> patched = new Dictionary<int, TMP_FontAsset>();
        static TMP_FontAsset gameNoto, fallbackAll;
        static bool loaded;

        public static TMP_FontAsset Serif => styles.TryGetValue("serif", out var f) ? f : null;
        public static TMP_FontAsset Noto => gameNoto;   // the game's own Noto Naskh: even strokes, so joins survive at subtitle sizes

        // Latin font asset name -> Arabic style
        // live overrides set by the `style` command: substring of the Latin font name -> style key
        public static readonly Dictionary<string, string> Override = new Dictionary<string, string>();

        public static string StyleFor(string name)
        {
            string n = (name ?? "").ToLowerInvariant();
            foreach (var kv in Override) if (n.Contains(kv.Key)) return kv.Value;
            if (n.Contains("grandpa") || n.Contains("nonna") || n.Contains("sloppy") || n.Contains("soft") || n.Contains("hand script tiny")) return "quirky";
            if (n.Contains("darchit") || n.Contains("angltrr")) return "sans"; // Katibeh's tall glyphs overlapped neighbouring lines
            if (n.StartsWith("hand") || n.Contains("script") || n.Contains("formosa")) return "hand";
            if (n.Contains("type") || n.Contains("remington") || n.Contains("liberation") || n.StartsWith("noto") || n.Contains("rasteroids")) return "sans";
            if (n.Contains("charcuterie") || n.Contains("arial black") || n.Contains("inventory") || n.Contains("white te")) return "sansbold";
            return "serif";
        }

        public static bool Ensure()
        {
            if (loaded) return fallbackAll != null;
            loaded = true;
            try
            {
                string dir = Path.Combine(Plugin.Dir, "fonts");
                foreach (var f in Files)
                {
                    string path = Path.Combine(dir, f[1]);
                    if (!File.Exists(path)) { Plugin.Log.LogWarning("missing font file " + path); continue; }
                    var font = new Font(path);
                    var asset = TMP_FontAsset.CreateFontAsset(font, 72, 8, GlyphRenderMode.SDFAA, 1024, 1024, AtlasPopulationMode.Dynamic, true);
                    if (asset == null) { Plugin.Log.LogWarning("CreateFontAsset failed for " + f[1]); continue; }
                    asset.name = "BPAR " + f[0];
                    UnityEngine.Object.DontDestroyOnLoad(asset);
                    styles[f[0]] = asset;
                    const string sample = "ﺑﻣﻻﺍﻟ";
                    string missing = "";
                    bool added = asset.TryAddCharacters(sample, out missing, false);
                    Plugin.Log.LogInfo($"Arabic font '{f[0]}' <- {f[1]} font.name='{font.name}' dynamic={font.dynamic} added={added} missing='{missing}' faces={asset.faceInfo.familyName}");
                }
                // safety net: the game's own Noto Naskh Arabic
                foreach (var f in Resources.FindObjectsOfTypeAll<Font>())
                {
                    if (f == null || !f.name.Contains("NotoNaskhArabic")) continue;
                    gameNoto = TMP_FontAsset.CreateFontAsset(f, 72, 8, GlyphRenderMode.SDFAA, 1024, 1024, AtlasPopulationMode.Dynamic, true);
                    if (gameNoto != null) { gameNoto.name = "BPAR noto"; UnityEngine.Object.DontDestroyOnLoad(gameNoto); }
                    break;
                }
                fallbackAll = styles.ContainsKey("serif") ? styles["serif"] : gameNoto;
            }
            catch (Exception e) { Plugin.Log.LogError("Arabic font setup failed: " + e); }
            return fallbackAll != null;
        }

        // drop our fallbacks and apply the current mapping again (used after `style` overrides)
        public static void Reapply()
        {
            patched.Clear();
            foreach (var fa in Resources.FindObjectsOfTypeAll<TMP_FontAsset>())
            {
                if (fa == null || fa.fallbackFontAssetTable == null) continue;
                var l = fa.fallbackFontAssetTable;
                for (int i = l.Count - 1; i >= 0; i--) { var x = l[i]; if (x != null && (x.name.StartsWith("BPAR"))) l.RemoveAt(i); }
            }
            PatchAllLoaded();
        }

        // Patch every loaded game font asset up front: patching lazily inside the first parse of a font showed boxes.
        public static void PatchAllLoaded()
        {
            if (!Ensure()) return;
            foreach (var fa in Resources.FindObjectsOfTypeAll<TMP_FontAsset>())
                if (fa != null) EnsureFallback(fa);
        }

        public static void EnsureFallback(TMP_FontAsset fa)
        {
            if (fa == null || fallbackAll == null) return;
            int id = fa.GetInstanceID();
            if (patched.ContainsKey(id)) return;
            string name = fa.name ?? "";
            if (name.StartsWith("BPAR")) { patched[id] = fa; return; }
            if (!styles.TryGetValue(StyleFor(name), out var want)) want = fallbackAll;
            patched[id] = want;
            var list = fa.fallbackFontAssetTable;
            if (list == null) { fa.fallbackFontAssetTable = new Il2CppSystem.Collections.Generic.List<TMP_FontAsset>(); list = fa.fallbackFontAssetTable; }
            if (!list.Contains(want)) list.Insert(0, want);
            if (gameNoto != null && !list.Contains(gameNoto)) list.Add(gameNoto);
        }
    }
}
